const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={tasks:[],source:''};try{const s=JSON.parse(localStorage.getItem('notice-first-v1'));if(s&&Array.isArray(s.tasks))state=s}catch{}let tab='todo',selected=null,pending=[],pendingSource='';
const icons={todo:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 11 3 3 5-6"/>',review:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v1"/>',past:'<path d="M3 12a9 9 0 1 0 3-7L3 8m0-5v5h5m4-1v6l4 2"/>',done:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',all:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h8"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[k]}</svg>`;
function save(){try{localStorage.setItem('notice-first-v1',JSON.stringify(state))}catch{toast('저장 공간이 부족해요. 이 탭을 닫기 전에 데이터를 확인해 주세요.')}}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
function fmt(d,short=false){return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',...(short?{month:'numeric',day:'numeric'}:{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})}).format(new Date(d))}
function status(t){if(t.done)return'done';if(!t.due||t.warnings.some(w=>w.includes('서로 다른')))return'review';if(new Date(t.due)<Date.now())return'past';return'todo'}
const day=d=>Math.floor((new Date(d).getTime()+9*3600000)/86400000);
function badge(t){if(t.done)return'제출 완료';if(!t.due)return'날짜 미정';let ms=new Date(t.due)-Date.now();if(ms<0)return'마감 지남';if(t.start&&new Date(t.start)>Date.now())return'접수 전';if(ms<3600000)return`${Math.max(1,Math.ceil(ms/60000))}분 남음`;if(ms<86400000)return`${Math.floor(ms/3600000)}시간 ${Math.floor(ms%3600000/60000)}분 남음`;return`D-${day(t.due)-day(Date.now())}`}
function openInput(){ $('importDialog').hidden=false;resetPreview();$('input').focus({preventScroll:true});$('importDialog').scrollIntoView({block:'start'}) }
function render(){let counts={todo:0,past:0,review:0,done:0};state.tasks.forEach(t=>counts[status(t)]++);let soon=state.tasks.filter(t=>status(t)==='todo'&&day(t.due)===day(Date.now())).length;$('stats').innerHTML=`<span class="today">오늘 마감 <strong>${soon}</strong></span><span>남은 과제 <strong>${counts.todo}</strong></span><span>제출 완료 <strong>${counts.done}</strong></span>`;const names={todo:'해야 할 과제',review:'확인 필요',past:'마감 지남',done:'제출 완료',all:'전체 과제'};$('pageTitle').textContent=names[tab];$('tabs').innerHTML=Object.entries(names).map(([k,n])=>`<button data-tab="${k}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${icon(k)}<span>${n}</span><small>${counts[k]??state.tasks.length}</small></button>`).join('');$('tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=null;$('detail').classList.remove('mobile-open');render()});let q=$('search').value.trim().toLowerCase();let tasks=state.tasks.filter(t=>(tab==='all'||status(t)===tab)&&(t.title+' '+t.raw).toLowerCase().includes(q)).sort((a,b)=>(new Date(a.due).getTime()||Infinity)-(new Date(b.due).getTime()||Infinity));if(!tasks.some(t=>t.id===selected))selected=tasks[0]?.id;$('listLabel').textContent=`${tasks.length}개 과제${tab==='past'?' · 제출 여부 확인':''}`;let lastGroup='';$('list').innerHTML=tasks.length?tasks.map(t=>{let group=tab==='todo'?(day(t.due)===day(Date.now())?'오늘 마감':'다가오는 마감'):'';let label=group&&group!==lastGroup?`<div class="group-label ${group==='오늘 마감'?'today':''}">${group}</div>`:'';lastGroup=group;return label+`<button class="task ${t.id===selected?'selected':''}" data-id="${esc(t.id)}" aria-label="${esc(t.title)} 상세 보기"><div><h3>${esc(t.title)}</h3><div class="meta"><span class="tag">${esc(t.kind)}</span>${t.warnings.length?'<span>확인 사항 있음</span>':''}</div></div><div class="date-col"><span class="badge ${status(t)==='todo'&&day(t.due)===day(Date.now())?'urgent':''}">${esc(badge(t))}</span><time>${t.due?esc(fmt(t.due,true)):'날짜 확인 필요'}</time></div></button>`}).join(''):`<div class="empty">${icon('all')}<b>${state.tasks.length?'표시할 과제가 없습니다':'아직 등록한 과제가 없습니다'}</b>${state.tasks.length?'다른 목록을 선택하거나 검색어를 바꿔보세요.':'위 입력창에 공지를 붙여 넣으면<br>과제와 마감일을 목록으로 정리합니다.'}${state.tasks.length?'':'<br><button id="emptyInput">공지 입력하기</button>'}</div>`;$('emptyInput')?.addEventListener('click',openInput);$('list').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();$('detail').classList.add('mobile-open');$('detail').scrollTop=0});detail()}
function detail(){const t=state.tasks.find(t=>t.id===selected);if(!t){$('detail').innerHTML=`<div class="empty">${icon('todo')}<b>과제 상세 정보</b>목록에서 과제를 선택하면<br>마감일과 제출 조건을 확인할 수 있습니다.</div>`;return}let checklines=t.raw.split('\n').filter(l=>l.trim()!==t.title.trim()&&!/https?:|^참고|^탐구주제|^과제\s*:|새\s*과제\s*게시|기한|기일|^\[|^\d+번|표시 중|\.(?:png|jpg|jpeg|pdf)$/.test(l)&&/제출|첨부|조건|본문|파일|가사|음원|기본|입력|구현|설명|반복|작성|읽고|해설|그림|생성|풀어|신청|활용/.test(l));$('detail').innerHTML=`<div class="detail-header"><span>과제 상세</span><button class="mobile-close" id="closeDetail">목록으로 돌아가기 ✕</button><button id="topEdit">수정</button></div><span class="tag">${esc(t.kind)}</span><h2>${esc(t.title)}</h2><div class="property"><span>${t.dueSource==='title'?'제목의 날짜':'마감일'}</span><strong>${t.due?esc(fmt(t.due)):'날짜 확인 필요'}<em>${esc(badge(t))}</em></strong></div>${t.start?`<div class="property"><span>접수 시작</span><strong>${esc(fmt(t.start))}</strong></div>`:''}<div class="property"><span>제출 상태</span><strong>${t.done?'제출 완료':'제출 완료로 표시하지 않음'}</strong></div>${t.warnings.length?`<div class="warn">${t.warnings.map(esc).join('<br>')}</div>`:''}<section class="keyword-section"><h4>원문 검색어 <span>Ctrl+F</span></h4><p class="hint">검색어를 복사한 뒤 원래 공지에서 Ctrl+F로 찾아보세요.</p><div class="keyword-list">${NoticeParser.keywords(t.title,t.raw).map((k,i)=>`<button data-keyword="${esc(k)}" aria-label="${esc(k)} 검색어 복사"><span>${esc(k)}</span><small>복사</small></button>`).join('')}</div><button class="text-button" id="findInSource">입력한 전체 원문에서 찾기 ↗</button></section><h4>준비할 내용</h4>${checklines.length?checklines.map((l,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${t.checks?.[i]?'checked':''}><span>${esc(l.replace(/^\d+[.．]\s+/,''))}</span></label>`).join(''):'<p class="hint">분리된 제출 조건이 없습니다. 아래 공지 원문에서 확인하세요.</p>'}${t.email?`<h4>제출처</h4><div class="links"><a href="mailto:${esc(t.email)}">${esc(t.email)} ↗</a></div>`:''}${t.links.length?`<h4>참고 자료 · 링크 ${t.links.length}</h4><div class="links">${t.links.map((l,i)=>`<a href="${esc(l)}" target="_blank" rel="noopener noreferrer">${esc(l.replace(/^https?:\/\//,''))} ↗</a>`).join('')}</div>`:''}<details><summary>공지 원문 보기</summary><pre>${esc(t.raw)}</pre></details><div class="detail-actions"><button id="edit">내용 수정</button><button class="primary" id="complete">${t.done?'완료 취소':'제출 완료로 표시'}</button></div><div id="editPanel"></div>`;$('detail').querySelectorAll('[data-keyword]').forEach(b=>b.onclick=async()=>{const text=b.dataset.keyword;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text)}else{const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();if(!ok)throw Error('copy');}toast('“'+text+'” 복사됨 · 원래 공지에서 Ctrl+F를 누르고 붙여 넣으세요.')}catch{toast('자동 복사가 되지 않았습니다. 검색어를 드래그해 Ctrl+C로 복사해 주세요.')}});$('findInSource').onclick=()=>{$('sourceText').textContent=state.source||t.raw;$('sourceDialog').showModal()};$('closeDetail').onclick=()=>$('detail').classList.remove('mobile-open');$('detail').querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{t.checks??={};t.checks[c.dataset.check]=c.checked;save()});$('complete').onclick=()=>{t.done=!t.done;save();render();toast(t.done?'제출 완료로 기록했습니다.':'완료 표시를 취소했습니다.')};$('topEdit').onclick=()=> $('edit').click();$('edit').onclick=()=>{let local=t.due?new Date(new Date(t.due).getTime()+9*3600000).toISOString().slice(0,16):'';$('editPanel').innerHTML=`<details open><summary>과제 정보 수정</summary><div class="edit-fields"><label>과제명<input id="editTitle" value="${esc(t.title)}"></label><label>마감일과 시각 (한국 시간)<input type="datetime-local" id="editDue" value="${local}"></label><label>접수 시작 (선택)<input type="datetime-local" id="editStart" value="${t.start?new Date(new Date(t.start).getTime()+9*3600000).toISOString().slice(0,16):''}"></label><label>분류<select id="editKind">${['과제','절대평가','상대평가','평가 외 활동','대회·신청'].map(k=>`<option ${k===t.kind?'selected':''}>${k}</option>`).join('')}</select></label><label><span><input type="checkbox" id="resolved"> 마감 관련 확인 사항을 확인했습니다</span></label><div><button id="saveEdit" class="primary">저장</button> <button id="deleteTask">삭제</button></div></div></details>`;$('editTitle').focus();$('saveEdit').onclick=()=>{let title=$('editTitle').value.trim(),d=$('editDue').value,s=$('editStart').value;if(!title)return toast('과제명을 입력해 주세요.');if(d&&s&&s>d)return toast('접수 시작은 마감보다 늦을 수 없습니다.');if(title!==t.title)t.titleEdited=true;t.title=title;if(d!==local){t.due=d?d+':00+09:00':'';t.dueEdited=true;t.dueSource='manual';}t.start=s?s+':00+09:00':null;t.kind=$('editKind').value;if($('resolved').checked){t.warnings=t.due?[]:['정확한 마감일 확인 필요'];t.dueSource='manual';t.dueEdited=true;}save();render();toast('수정했습니다.')};$('deleteTask').onclick=()=>{if(confirm('이 과제를 목록에서 삭제할까요? 입력 원문은 남습니다.')){state.tasks=state.tasks.filter(x=>x!==t);save();render()}}}}
function resetPreview(){$('preview').hidden=true;$('inputFields').hidden=false;$('step1').classList.add('current');$('step2').classList.remove('current');$('importError').textContent=''}
function countText(){$('charCount').textContent=$('input').value.length.toLocaleString()+'자';$('analyze').disabled=!$('input').value.trim()}
$('openImport').onclick=openInput;$('closeImport').onclick=()=>{$('importDialog').hidden=true};$('sourceBtn').onclick=()=>{$('sourceText').textContent=state.source||'입력된 공지가 없습니다.';$('sourceDialog').showModal()};$('search').oninput=render;$('input').oninput=countText;
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)return toast('2MB 이하의 텍스트 파일을 선택해 주세요.');$('input').value=await f.text();countText();$('importError').textContent=f.name+' 파일을 불러왔습니다. 아래 과제 추출하기를 눌러주세요.'};
$('sample').onclick=async()=>{try{const r=await fetch('sample.txt');if(!r.ok)throw Error();$('input').value=await r.text();$('year').value='2026';countText();$('importError').textContent='2026년 공지를 요약한 예시입니다. 과제 추출하기를 눌러 확인해 보세요.'}catch{toast('예시를 불러오지 못했습니다. 공지를 직접 붙여 넣어주세요.')}};
$('analyze').onclick=()=>{const text=$('input').value.trim(),year=+$('year').value;if(!text)return $('importError').textContent='공지를 입력해 주세요.';if(!Number.isInteger(year)||year<2000||year>2100)return $('importError').textContent='기준 연도는 2000~2100 사이의 정수로 입력해 주세요.';pending=NoticeParser.parse(text,year);pendingSource=text;if(!pending.length)return $('importError').textContent='과제를 찾지 못했습니다. 제목과 제출기한을 확인해 주세요.';$('inputFields').hidden=true;$('preview').hidden=false;$('step1').classList.remove('current');$('step2').classList.add('current');$('importError').textContent='';const duplicates=pending.filter(t=>state.tasks.some(x=>x.raw===t.raw)).length;$('preview').innerHTML=`<div class="preview-summary"><strong>${pending.length}개 항목을 찾았습니다</strong><span>날짜 미정 ${pending.filter(t=>!t.due).length}개${duplicates?' · 이미 등록된 항목 '+duplicates+'개':''}</span></div><p class="hint">추가할 항목을 선택하세요. 과제명과 마감일은 추가 후 상세 화면에서 수정할 수 있습니다.</p><div class="preview-table">${pending.map((t,i)=>`<label class="preview-row"><input type="checkbox" data-pending="${i}" checked><span>${esc(t.title)}</span><small class="${!t.due?'review':''}">${t.due?esc(fmt(t.due)):'날짜 확인 필요'}${t.dueSource==='title'?'<br>제목의 날짜 · 확인 필요':''}</small></label>`).join('')}</div><div class="preview-actions"><label><input type="checkbox" id="replace"> 기존 목록을 지우고 새로 등록</label><div><button id="backInput">← 입력 수정</button> <button id="confirmAdd" class="primary">선택한 과제 추가</button></div></div>`;$('backInput').onclick=resetPreview;$('confirmAdd').onclick=()=>{let chosen=[...$('preview').querySelectorAll('[data-pending]:checked')].map(c=>pending[+c.dataset.pending]);if(!chosen.length)return toast('추가할 항목을 선택해 주세요.');if($('replace').checked)state={tasks:[],source:''};let added=0;chosen.forEach(t=>{if(state.tasks.some(x=>x.raw===t.raw))return;t.id=crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);state.tasks.push(t);added++});if(added)state.source+=(state.source?'\n\n──────── 추가된 공지 ────────\n\n':'')+pendingSource;save();const addedTask=state.tasks.find(t=>t.raw===chosen[0].raw);tab=addedTask?status(addedTask):'all';selected=addedTask?.id;render();$('importDialog').hidden=true;resetPreview();$('input').value='';countText();toast(added?`${added}개 과제를 추가했습니다.`:'이미 등록된 공지입니다. 중복으로 추가하지 않았습니다.')};};
// Upgrade only unrecognized fields; preserve manual dates and completion state.
const migrationYear=+new Intl.DateTimeFormat('en',{timeZone:'Asia/Seoul',year:'numeric'}).format(new Date());
let repaired=0;state.tasks.forEach(t=>{if(NoticeParser.upgradeTask(t,migrationYear))repaired++});if(repaired)save();
function tick(){$('clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}
$('year').value=new Intl.DateTimeFormat('en',{timeZone:'Asia/Seoul',year:'numeric'}).format(new Date());$('importDialog').hidden=state.tasks.length>0;countText();tick();render();setInterval(()=>{tick();if(!$('editPanel')?.querySelector('details'))render()},30000);
